BEGIN TRANSACTION;
CREATE TABLE alerts(key TEXT PRIMARY KEY, entity TEXT, condition TEXT, state TEXT, first_fired TEXT, last_fired TEXT,
  last_values TEXT, times_fired INTEGER, acknowledged_at TEXT);
CREATE TABLE edges(src TEXT, rel TEXT, dst TEXT, props TEXT, first_observed TEXT, last_observed TEXT, status TEXT, PRIMARY KEY(src, rel, dst));
CREATE TABLE facts(id INTEGER PRIMARY KEY, entity TEXT, attribute TEXT, value TEXT, value_num REAL,
  observed_at TEXT, first_observed TEXT, source TEXT, confidence REAL, status TEXT, is_current INTEGER,
  prev_value TEXT, change REAL, rate_per_30d REAL, run_id TEXT, last_verified TEXT);
CREATE TABLE ledger(id TEXT PRIMARY KEY, kind TEXT, entity TEXT, text TEXT, data TEXT, created_at TEXT, run_id TEXT,
  status TEXT, links TEXT, next_review TEXT, confidence REAL);
CREATE TABLE nodes(id TEXT PRIMARY KEY, type TEXT, label TEXT, props TEXT, first_observed TEXT, last_observed TEXT, status TEXT);
CREATE TABLE prefs(key TEXT PRIMARY KEY, value TEXT, set_at TEXT);
CREATE TABLE profile(id INTEGER PRIMARY KEY CHECK(id=1), data TEXT, updated_at TEXT);
CREATE TABLE runs(run_id TEXT PRIMARY KEY, at TEXT, question TEXT, intent TEXT, tier TEXT, reason TEXT, tokens INTEGER,
  escalated INTEGER, confidence REAL);
CREATE TABLE sources(name TEXT PRIMARY KEY, schema_hash TEXT, columns TEXT, rows INTEGER, last_refresh TEXT,
  max_age_days INTEGER, quality TEXT, status TEXT, limitations TEXT, history TEXT);
CREATE TABLE summaries(run_id TEXT, entity TEXT, summary TEXT, at TEXT, PRIMARY KEY(run_id, entity));
